package dedupe

import (
	"reflect"
	"testing"
)

func TestDedupe(t *testing.T) {
	cases := []struct {
		in, want []string
	}{
		{[]string{"b", "a", "b", "c", "a"}, []string{"b", "a", "c"}},
		{[]string{"x"}, []string{"x"}},
		{[]string{}, []string{}},
	}
	for _, c := range cases {
		got := Dedupe(c.in)
		if len(got) == 0 && len(c.want) == 0 {
			continue
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("Dedupe(%v) = %v, want %v", c.in, got, c.want)
		}
	}
}

